INSERT INTO pages (page_id, parent_type, parent_id, title, archived, created_time, last_edited_time, properties_json, icon, cover) VALUES ('744a360b-59b9-5980-86d7-af583779aa4f', 'workspace', 'ws_yuhan_bike', 'Jing''an to Xuhui bicycle commuting route materials', 0, '2026-07-06T08:30:00+08:00', '2026-07-06T09:12:00+08:00', '{"type":"route_reference"}', NULL, NULL);
INSERT OR REPLACE INTO blocks VALUES
('bda93cfe-448e-5925-8931-2c40a011239c',NULL,'744a360b-59b9-5980-86d7-af583779aa4f','paragraph','{"text":"This page compiles intersection, road surface, parking point, and public transit connection information for three candidate routes."}',0,0,0,'2026-07-06T08:30:00+08:00','2026-07-06T08:30:00+08:00'),
('58900062-101d-5d91-b930-83d69a6e65a3',NULL,'744a360b-59b9-5980-86d7-af583779aa4f','paragraph','{"text":"Route A is approximately 8.0 km via Xinzhha Road and Changshu Road; the left-turn queue at the West Nanjing Road intersection is long during the morning rush."}',0,0,1,'2026-07-06T08:31:00+08:00','2026-07-06T08:31:00+08:00'),
('25de1829-ee6c-5f3f-bcb0-c137440517c7',NULL,'744a360b-59b9-5980-86d7-af583779aa4f','paragraph','{"text":"Route B is approximately 8.6 km along Suzhou Creek and South Shaanxi Road; three streetlights along a 600-meter riverside section are awaiting repairs."}',0,0,2,'2026-07-06T08:32:00+08:00','2026-07-06T08:32:00+08:00'),
('abd9cfe6-016d-59ab-92e4-261023c3c099',NULL,'744a360b-59b9-5980-86d7-af583779aa4f','paragraph','{"text":"Route C consists of Metro Line 12 plus 1.4 km of walking; both Changping Road Station and Jiashan Road Station have elevators."}',0,0,3,'2026-07-06T08:33:00+08:00','2026-07-06T08:33:00+08:00'),
('ff3e3704-939e-5f48-97a0-146840962994',NULL,'744a360b-59b9-5980-86d7-af583779aa4f','paragraph','{"text":"There is heavy motor-vehicle right-turn traffic at the south entrance of Hengfeng Road Bridge on Route A, with a noticeable queue from 07:45 to 08:30."}',0,0,4,'2026-07-06T08:34:00+08:00','2026-07-06T08:34:00+08:00'),
('4f0221e3-75e0-5eb6-b1a5-fc24ee4ef777',NULL,'744a360b-59b9-5980-86d7-af583779aa4f','paragraph','{"text":"The Jiangning Road section of Route B has a relatively smooth road surface, but the riverside side floods after rain and has many manhole covers."}',0,0,5,'2026-07-06T08:35:00+08:00','2026-07-06T08:35:00+08:00'),
('bac8b2d7-9072-5e7c-93dc-99c09eaa9257',NULL,'744a360b-59b9-5980-86d7-af583779aa4f','paragraph','{"text":"The bicycle entrance at the Xuhui office is on the south gate ramp, which is open from 07:00 to 22:30 on workdays."}',0,0,6,'2026-07-06T08:36:00+08:00','2026-07-06T08:36:00+08:00'),
('1d309dc9-0ee4-522e-93a8-c56a255303ad',NULL,'744a360b-59b9-5980-86d7-af583779aa4f','paragraph','{"text":"The west section of Basement Level 2 has 24 bike racks; 8 spaces in the east section were temporarily closed during maintenance in June."}',0,0,7,'2026-07-06T08:37:00+08:00','2026-07-06T08:37:00+08:00'),
('0bf64260-f83d-5606-b288-1efeee9f2b30',NULL,'744a360b-59b9-5980-86d7-af583779aa4f','paragraph','{"text":"The office building''s shower room is on B1. The lockers require you to bring your own small lock, and towels must also be brought separately."}',0,0,8,'2026-07-06T08:38:00+08:00','2026-07-06T08:38:00+08:00'),
('8029d865-cb76-52e1-a35c-061e00025e3f',NULL,'744a360b-59b9-5980-86d7-af583779aa4f','paragraph','{"text":"The Jing''an residence is approximately 650 meters from the starting point of Route A; after leaving the residential complex, the route first passes through a narrow road and a delivery loading area."}',0,0,9,'2026-07-06T08:39:00+08:00','2026-07-06T08:39:00+08:00'),
('a3631182-f517-56b4-9a65-08bd3d497ee8',NULL,'744a360b-59b9-5980-86d7-af583779aa4f','paragraph','{"text":"Water refill points along Route A: the convenience store at the east gate of Jing''an Park and the public drinking fountain on North Xiangyang Road."}',0,0,10,'2026-07-06T08:40:00+08:00','2026-07-06T08:40:00+08:00'),
('a84d1a68-ed90-5672-b9bf-53b8b6276e56',NULL,'744a360b-59b9-5980-86d7-af583779aa4f','paragraph','{"text":"Repair shops along Route B open at 10:00 on workdays and operate only until 16:00 on Sundays."}',0,0,11,'2026-07-06T08:41:00+08:00','2026-07-06T08:41:00+08:00'),
('5be401bc-e4af-52a7-b75e-c83dc1b7c19c',NULL,'744a360b-59b9-5980-86d7-af583779aa4f','paragraph','{"text":"The shared bicycle parking geofence is 80 meters outside the office''s south gate, not inside the underground parking garage."}',0,0,12,'2026-07-06T08:42:00+08:00','2026-07-06T08:42:00+08:00'),
('ee0ad3b9-b9c0-5400-915b-e30740ce61cf',NULL,'744a360b-59b9-5980-86d7-af583779aa4f','paragraph','{"text":"June 24 walking inspection record: both roadworks warning signs on Route A were located at the edge of the non-motorized lane."}',0,0,13,'2026-07-06T08:43:00+08:00','2026-07-06T08:43:00+08:00'),
('88a42017-dac1-5940-8837-027aa486fe14',NULL,'744a360b-59b9-5980-86d7-af583779aa4f','paragraph','{"text":"On June 27, a closed area of the parking lot was used for practice, covering starts, straight-line riding, and low-speed turns."}',0,0,14,'2026-07-06T08:44:00+08:00','2026-07-06T08:44:00+08:00'),
('93164d2d-bab9-58a5-b1cc-f02517e998b7',NULL,'744a360b-59b9-5980-86d7-af583779aa4f','paragraph','{"text":"The desk drawer can hold gloves and charging cables, but not a helmet; use the B2 locker instead."}',0,0,15,'2026-07-06T08:45:00+08:00','2026-07-06T08:45:00+08:00'),
('eec2bb93-2951-5e71-ae14-fe8fefd94a27',NULL,'744a360b-59b9-5980-86d7-af583779aa4f','paragraph','{"text":"The company front desk can accept ordinary parcels, but boxes over 60 cm must be collected from the rack in person."}',0,0,16,'2026-07-06T08:46:00+08:00','2026-07-06T08:46:00+08:00'),
('5162e91e-aacc-56a7-898f-7a2cb0f33eee',NULL,'744a360b-59b9-5980-86d7-af583779aa4f','paragraph','{"text":"The south gate ramp entrance is 2.1 meters high. There is a convex mirror at the turn at the bottom of the ramp, and cleaning carts occasionally stop there in the morning."}',0,0,17,'2026-07-06T08:47:00+08:00','2026-07-06T08:47:00+08:00'),
('c0fc0444-4b98-5a80-93c4-f27afa95f13b',NULL,'744a360b-59b9-5980-86d7-af583779aa4f','paragraph','{"text":"The route materials were last verified on July 6; roadworks and lighting information should be based on subsequent announcements."}',0,0,18,'2026-07-06T08:48:00+08:00','2026-07-06T08:48:00+08:00');
